INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(47985614, 'Gadget Arms', '工具抓手', 'ガジェット・アームズ', 'Flip Effect Monster', 'Machine', 'WATER', 2, 200, 400, '反转：选择自己墓地存在的1张名字带有「变形斗士」的魔法或者陷阱卡加入手卡。'),
(8025950, 'Gadget Box', '工具箱子', 'ガジェット・ボックス', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「变形斗士」卡使用。这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，给这张卡放置3个变形斗士指示物。 ②：1回合1次，自己主要阶段才能发动。自己场上1个变形斗士指示物取除，在自己场上把1只「工具箱子衍生物」（机械族·地·1星·攻/守0）特殊召唤。只要这个效果特殊召唤的衍生物存在，自己不是同调怪兽不能从额外卡组特殊召唤。'),
(54497620, 'Gadget Driver', '工具起子', 'ガジェット・ドライバー', 'Effect Monster', 'Machine', 'EARTH', 1, 200, 200, '①：把这张卡从手卡送去墓地，以自己场上的「变形斗士」怪兽任意数量为对象才能发动。那些自己的「变形斗士」怪兽的表示形式变更。这个效果在对方回合也能发动。'),
(64487132, 'Gadget Gamer', '工具游戏本', 'ガジェット・ゲーマー', 'Effect Monster', 'Machine', 'EARTH', 3, 300, 300, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤成功时才能发动。从卡组把1只机械族·1星怪兽加入手卡。 ②：把这张卡解放才能发动。从手卡把1只「变形斗士」怪兽特殊召唤。那之后，可以从手卡·卡组把1只「工具挂车」特殊召唤。'),
(28002611, 'Gadget Hauler', '工具挂车', 'ガジェット・トレーラー', 'Effect Monster', 'Machine', 'EARTH', 6, 1300, NULL, '①：1回合1次，自己主要阶段才能发动。从手卡选「变形斗士」怪兽任意数量送去墓地。这张卡的攻击力上升这个效果送去墓地的怪兽数量×800。'),
(86281779, 'Gadget Soldier', '齿轮战士', 'ガジェット・ソルジャー', 'Normal Monster', 'Machine', 'FIRE', 6, 1800, 2000, '为战斗而制造的机械战士。用不生锈金属制成。'),
(92110878, 'Gadget Trio', '三色小工具', 'トリコロール・ガジェット', 'Effect Monster', 'Machine', 'EARTH', 4, 1300, 1100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。把1张「光之黄金柜」或者有那个卡名记述的魔法·陷阱卡从卡组加入手卡。 ②：这张卡被战斗·效果破坏的场合才能发动。从卡组把1张「隐藏城 堡垒」在自己场上盖放。'),
(21715135, 'Gagaga Academy Emergency Network', '我我我学园的紧急联络网', 'ガガガ学園の緊急連絡網', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不能作超量召唤以外的特殊召唤。 ①：只有对方场上才有怪兽存在的场合才能发动。从卡组把1只「我我我」怪兽特殊召唤。'),
(9583383, 'Gagaga Caesar', '我我我凯撒', 'ガガガカイザー', 'Effect Monster', 'Warrior', 'EARTH', 3, 1800, 600, '这张卡在自己场上有这张卡以外的名字带有「我我我」的怪兽存在的场合才能攻击。此外，1回合1次，把自己墓地1只怪兽从游戏中除外才能发动。自己场上的全部名字带有「我我我」的怪兽的等级变成和为这个效果发动而从游戏中除外的怪兽相同等级。这张卡不能作为同调素材。'),
(94203886, 'Gagaga Child', '我我我小子', 'ガガガキッド', 'Effect Monster', 'Spellcaster', 'DARK', 2, 800, 1200, '自己场上有「我我我小子」以外的名字带有「我我我」的怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤成功时，可以选择自己场上1只名字带有「我我我」的怪兽，这张卡的等级变成和选择的怪兽相同等级。这个效果发动的回合，自己不能进行战斗阶段。'),
(44250812, 'Gagaga Clerk', '我我我书记', 'ガガガクラーク', 'Effect Monster', 'Warrior', 'EARTH', 2, 400, 800, '①：自己场上有「我我我书记」以外的「我我我」怪兽存在的场合，这张卡可以从手卡特殊召唤。'),
(12014404, 'Gagaga Cowboy', '我我我枪手', 'ガガガガンマン', 'XYZ Monster', 'Warrior', 'EARTH', 4, 1500, 2400, '4星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。这张卡的表示形式的以下效果适用。 ●攻击表示：这个回合，这张卡向对方怪兽攻击的伤害步骤内，这张卡的攻击力上升1000，那只对方怪兽的攻击力下降500。 ●守备表示：给与对方800伤害。'),
(9591819, 'Gagaga Escape', '我我我逃脱剧', 'ガガガの脱出劇', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「我我我」怪兽存在，对方把怪兽的效果发动时才能发动。那个发动无效。那之后，以下效果可以适用。 ●选自己1张手卡丢弃，从卡组把1只「我我我」怪兽特殊召唤。 ②：把墓地的这张卡除外才能发动。自己场上的「我我我」怪兽全部变成守备表示，这个回合中，自己场上的「我我我」怪兽不会被战斗·效果破坏。'),
(9491461, 'Gagaga Ganbara Knight', '我我我加把劲骑士', 'ガガガガンバラナイト', 'Effect Monster', 'Warrior', 'LIGHT', 4, NULL, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：把额外卡组1只「我我我」怪兽给对方观看才能发动。这张卡从手卡特殊召唤。那之后，可以从以下效果选1个适用。 ●从手卡把1只「我我我」怪兽特殊召唤。 ●场上1只怪兽的表示形式变更。 ②：超量素材的这张卡为让超量怪兽的效果发动而被取除的场合才能发动。从卡组把1只「隆隆隆」怪兽加入手卡。'),
(12423762, 'Gagaga Gardna', '我我我守卫', 'ガガガガードナー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1500, 2000, '对方怪兽的直接攻击宣言时，这张卡可以从手卡特殊召唤。此外，这张卡被选择作为攻击对象时，可以丢弃1张手卡，这张卡不会被那次战斗破坏。'),
(3606728, 'Gagaga Girl', '我我我女孩', 'ガガガガール', 'Effect Monster', 'Spellcaster', 'DARK', 3, 1000, 800, '①：以自己场上1只「我我我魔术师」为对象才能发动。这张卡的等级变成和那只怪兽相同。 ②：只用包含这张卡的场上的「我我我」怪兽为素材作超量召唤的怪兽得到以下效果。 ●这张卡超量召唤时，以对方场上1只特殊召唤的怪兽为对象才能发动。那只怪兽的攻击力变成0。'),
(67120578, 'Gagaga Head', '我我我老大', 'ガガガヘッド', 'Effect Monster', 'Spellcaster', 'DARK', 6, 2100, 2000, '①：只有对方场上才有怪兽存在的场合，这张卡可以不用解放并作为4星怪兽召唤。 ②：这张卡召唤成功时，以「我我我首领」以外的自己墓地最多2只「我我我」怪兽为对象才能发动。那些怪兽特殊召唤。这个回合自己不能作除只用「我我我」怪兽为素材的超量召唤以外的特殊召唤。 ③：场上的这张卡为素材作超量召唤的怪兽得到以下效果。 ●这次超量召唤成功的场合发动。自己从卡组抽1张。'),
(73496100, 'Gagaga Illusion', '我我我幻象', 'ガガガイリュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「我我我」怪兽存在的场合，以自己墓地1只怪兽为对象才能发动。那只怪兽特殊召唤。那之后，可以把那只怪兽的等级·阶级变成和自己场上1只「我我我」怪兽的等级·阶级的数值相同。 ②：把这个回合没有送去墓地的这张卡从墓地除外才能发动。进行1只「我我我」怪兽的召唤。'),
(26082117, 'Gagaga Magician', '我我我魔术师', 'ガガガマジシャン', 'Effect Monster', 'Spellcaster', 'DARK', 4, 1500, 1000, '这张卡不能作为同调素材。 ①：「我我我魔术师」在自己场上只能有1只表侧表示存在。 ②：1回合1次，宣言1～8的任意等级才能发动。这张卡的等级直到回合结束时变成宣言的等级。'),
(28884172, 'Gagaga Mancer', '我我我巫师', 'ガガガマンサー', 'Effect Monster', 'Spellcaster', 'DARK', 4, 100, 100, '①：1回合1次，以「我我我术士」以外的自己墓地1只「我我我」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是「我我我」怪兽不能特殊召唤。 ②：超量素材的这张卡为让超量怪兽的效果发动而被取除送去墓地的场合，以自己场上1只超量怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升500。'),
(91499077, 'Gagaga Samurai', '我我我武士', 'ガガガザムライ', 'XYZ Monster', 'Warrior', 'EARTH', 4, 1900, 1600, '4星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以自己场上1只「我我我」怪兽为对象才能发动。这个回合，那只怪兽在同1次的战斗阶段中可以作2次攻击。 ②：这张卡以外的自己怪兽被选择作为攻击对象时才能发动。这张卡变成表侧守备表示，攻击对象转移为这张卡进行伤害计算。'),
(387282, 'Gagaga Sister', '我我我妹妹', 'ガガガシスター', 'Effect Monster', 'Spellcaster', 'DARK', 2, 200, 800, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤成功时才能发动。从卡组把1张「我我我」魔法·陷阱卡加入手卡。 ②：以这张卡以外的自己场上1只「我我我」怪兽为对象才能发动。那只怪兽和这张卡直到回合结束时变成那2只的等级合计的等级。'),
(75956913, 'Gagaga Utopic Tactics', '我我我霍普战术', 'ガガガ・ホープ・タクティクス', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：自己场上的原本属性是光属性的「霍普」超量怪兽不会被效果破坏，对方不能把那些作为效果的对象。 ②：宣言1～12的任意等级，以包含「我我我」怪兽的自己场上2只表侧表示怪兽为对象才能发动。那些怪兽的等级变成宣言的等级。 ③：原本属性是光属性的「霍普」超量怪兽由自己超量召唤的场合，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(82052602, 'Gagagaback', '我我我回归', 'ガガガバック', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '自己场上的名字带有「我我我」的怪兽被战斗破坏送去墓地的回合才能发动。这个回合被战斗破坏的怪兽尽可能从自己墓地表侧守备表示特殊召唤。那之后，这个效果特殊召唤的怪兽每有1只，自己受到600分伤害。「我我我回归」在1回合只能发动1张。'),
(17494901, 'Gagagabolt', '我我我雷击', 'ガガガボルト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有名字带有「我我我」的怪兽存在的场合才能发动。选择场上1张卡破坏。'),
(21831848, 'Gagagadraw', '我我我抽牌', 'ガガガドロー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己墓地3只名字带有「我我我」的怪兽从游戏中除外才能发动。从卡组抽2张卡。'),
(88917691, 'Gagagaga Girl', '我我我我女孩', 'ガガガガガール', 'XYZ Monster', 'Spellcaster', 'DARK', 4, 1500, 1800, '4星怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：这张卡有「刷拉拉」、「我我我」、「隆隆隆」、「怒怒怒」卡的其中任意种在作为超量素材的场合，把这张卡1个超量素材取除才能发动。「我我我」、「拟声」、「超量」卡的其中1张从卡组加入手卡。 ②：有这张卡在作为超量素材中的「未来皇 霍普」超量怪兽得到以下效果。 ●这张卡超量召唤的场合发动。这个回合，这张卡在同1次的战斗阶段中可以作2次攻击。'),
(86331741, 'Gagagaga Magician', '我我我我魔术师', 'ガガガガマジシャン', 'XYZ Monster', 'Spellcaster', 'DARK', 4, 2000, 2000, '4星怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：把这张卡1个超量素材取除，以「我我我我魔术师」以外的自己墓地1只超量怪兽为对象才能发动。那只怪兽效果无效特殊召唤。 ②：有这张卡在作为超量素材中的「未来皇 霍普」超量怪兽得到以下效果。 ●把这张卡2个超量素材取除，以自己场上1只超量怪兽为对象才能发动。直到回合结束时，那只怪兽的攻击力变成4000，效果无效化。'),
(76972801, 'Gagagaguard', '我我我防御', 'ガガガガード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有名字带有「我我我」的怪兽2只以上存在的场合才能发动。这个回合，自己场上的怪兽不会被战斗以及卡的效果破坏。'),
(90673413, 'Gagagarevenge', '我我我复仇', 'ガガガリベンジ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：以自己墓地1只「我我我」怪兽为对象才能把这张卡发动。那只怪兽特殊召唤，把这张卡装备。这张卡从场上离开时那只怪兽破坏。 ②：装备怪兽变成超量素材让这张卡被送去墓地的场合发动。自己场上的全部超量怪兽的攻击力上升300。'),
(13166204, 'Gagagarush', '我我我突击', 'ガガガラッシュ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的名字带有「我我我」的怪兽成为对方怪兽的效果的对象时才能发动。那只对方怪兽的效果无效并破坏。那之后，给与对方基本分破坏的怪兽的攻击力和守备力之内较高方数值的伤害。'),
(18446701, 'Gagagashield', '我我我护盾', 'ガガガシールド', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只魔法师族怪兽为对象才能把这张卡发动。这张卡当作装备卡使用给那只自己的魔法师族怪兽装备。装备怪兽1回合最多2次不会被战斗·效果破坏。'),
(917796, 'Gagagatag', '我我我搭档', 'ガガガタッグ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的全部名字带有「我我我」的怪兽的攻击力直到下次的自己的准备阶段时上升自己场上的名字带有「我我我」的怪兽数量×500的数值。「我我我组队」在1回合只能发动1张。'),
(57782164, 'Gagagawind', '我我我之风', 'ガガガウィンド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从手卡把1只名字带有「我我我」的怪兽特殊召唤。这个效果特殊召唤的怪兽的等级变成4星。'),
(49003308, 'Gagagigo', '咖咖吉哥', 'ガガギゴ', 'Normal Monster', 'Reptile', 'WATER', 4, 1850, 1000, '虽然曾经拥有邪恶的心灵，但是由于遇见某个人物而觉醒了正义之心的年轻恶魔。'),
(9053187, 'Gagagigo the Risen', '觉醒的勇士 魔蜥义豪', '覚醒の勇士 ガガギゴ', 'XYZ Monster', 'Reptile', 'WATER', 4, 2950, 2800, '4星怪兽×3'),
(17691568, 'Gagaku-P.U.N.K. Crash Beat', '雅－朋.克.轰击', 'Ga－P.U.N.K.クラッシュ・ビート', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己的「朋克」怪兽为对象的效果由对方发动的场合，以对方场上1张卡为对象才能发动。那张卡破坏。 ②：魔法与陷阱区域的这张卡被对方的效果破坏的场合才能发动。自己场上的全部「朋克」怪兽在这个回合不会成为对方的效果的对象，不会被对方的效果破坏。'),
(50642380, 'Gagaku-P.U.N.K. Wa Gon', '雅－朋.克.和琴', 'Ga－P.U.N.K.ワゴン', 'Tuner Monster', 'Psychic', 'EARTH', 3, 900, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：支付600基本分才能发动。从卡组把1张「朋克」魔法卡加入手卡。 ②：自己场上的「朋克」怪兽成为对方的效果的对象时或者被选择作为对方怪兽的攻击对象时才能发动。自己抽1张。'),
(81192859, 'Gagaku-P.U.N.K. Wild Picking', '雅－朋.克.狂奏', 'Ga－P.U.N.K.ワイルド・ピッキング', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己的「朋克」怪兽和对方怪兽进行战斗的伤害步骤开始时才能发动。那只对方怪兽破坏。 ②：魔法与陷阱区域的这张卡被对方的效果破坏的场合才能发动。自己场上的全部「朋克」怪兽在这个回合不会被战斗破坏。'),
(9709452, 'Gaia Blaze, the Force of the Sun', '烈日骑士盖亚烈焰', '烈日の騎士ガイアブレイズ', 'Synchro Monster', 'Pyro', 'FIRE', 7, 2600, 2100, '调整＋调整以外的怪兽1只以上 ①：这张卡的攻击破坏对方怪兽时才能发动。这张卡只再1次可以继续攻击。 ②：自己·对方的战斗阶段结束时，以最多有这个回合这张卡战斗破坏的怪兽数量的自己墓地的炎属性怪兽为对象才能发动。那些怪兽加入手卡。'),
(91949988, 'Gaia Dragon, the Thunder Charger', '迅雷骑士盖亚龙骑兵', '迅雷の騎士ガイアドラグーン', 'XYZ Monster', 'Dragon', 'WIND', 7, 2600, 2100, '7星怪兽×2 这张卡也能在自己场上的5·6阶的超量怪兽上面重叠来超量召唤。 ①：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(58601383, 'Gaia Drake, the Universal Force', '地天之骑士 盖亚德雷克', '地天の騎士ガイアドレイク', 'Fusion Monster', 'Beast-Warrior', 'EARTH', 10, 3500, 2800, '「大地之骑士 盖亚骑士」＋效果怪兽以外的同调怪兽 ①：只要这张卡在怪兽区域存在，这张卡不会被怪兽的效果破坏，双方不能把这张卡作为怪兽的效果的对象。'),
(97204936, 'Gaia Knight, the Force of Earth', '大地之骑士 盖亚骑士', '大地の騎士ガイアナイト', 'Synchro Monster', 'Warrior', 'EARTH', 6, 2600, 800, '调整＋调整以外的怪兽1只以上'),
(14258627, 'Gaia Plate the Earth Giant', '地球巨人', '地球巨人 ガイア・プレート', 'Effect Monster', 'Rock', 'EARTH', 8, 2800, 1000, '这张卡的控制者在每次自己准备阶段从自己墓地把1只岩石族怪兽除外。或者不除外让这张卡送去墓地。 ①：这张卡可以把自己墓地2只岩石族怪兽除外，从手卡特殊召唤。 ②：和这张卡进行战斗的对方怪兽的攻击力·守备力只在伤害计算时变成一半。'),
(56594520, 'Gaia Power', '大地力量', 'ガイアパワー', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '全部的地属性的怪兽攻击力上升500，守备力下降400。'),
(95095116, 'Gaia Prominence, the Fierce Force', '炽天骑士盖亚日珥', '熾天の騎士ガイアプロミネンス', 'Fusion Monster', 'Pyro', 'FIRE', 11, 3500, 3100, '「烈日之骑士 盖亚烈焰」＋自己场上的表侧表示怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：对方把手卡·墓地的怪兽的效果发动时，从手卡丢弃1只怪兽才能发动。那个效果无效并破坏。 ②：这张卡的攻击破坏对方怪兽时，以自己墓地1只炎属性怪兽为对象才能发动。那只怪兽特殊召唤。'),
(67598234, 'Gaia Saber, the Lightning Shadow', '电光骑士盖亚军刀士', '電影の騎士ガイアセイバー', 'Link Monster', 'Machine', 'EARTH', NULL, 2600, NULL, '怪兽2只以上'),
(51355346, 'Gaia Soul the Combustible Collective', '爆炎集合体 地球之魂', '爆炎集合体 ガイヤ・ソウル', 'Effect Monster', 'Pyro', 'FIRE', 4, 2000, NULL, '可以把自己场上最多2只炎族怪兽做祭品。因这个效果使用祭品的场合，这张卡的攻击力上升祭品数量×1000的数值。这张卡攻击守备表示怪兽时，若这张卡的攻击力超过守备表示怪兽的守备力，给与对方基本分那个数值的战斗伤害。结束阶段时这张卡破坏。'),
(13289758, 'Gaia Stream, the Graceful Force', '流丽骑士盖亚奔流', '流麗の騎士ガイアストリーム', 'XYZ Monster', 'Aqua', 'WATER', 6, NULL, NULL, '6星怪兽×2只以上 「流丽之骑士 盖亚激流」1回合1次也能在自己场上的5·7阶的超量怪兽上面重叠来超量召唤。这张卡在超量召唤的回合不能作为超量召唤的素材。 ①：这张卡不能直接攻击。 ②：这张卡的攻击力上升这张卡作为超量素材中的怪兽的等级·阶级的合计×200。 ③：这张卡进行战斗的伤害步骤结束时发动。这张卡1个超量素材取除。'),
(66889139, 'Gaia the Dragon Champion', '龙骑士盖亚', '竜騎士ガイア', 'Fusion Monster', 'Dragon', 'WIND', 7, 2600, 2100, '「暗黑骑士 盖亚」＋「诅咒之龙」'),
(6368038, 'Gaia The Fierce Knight', '暗黑骑士盖亚', '暗黒騎士ガイア', 'Normal Monster', 'Warrior', 'EARTH', 7, 2300, 2100, '乘坐跑得比风更快之马的骑士。要注意突进攻击。'),
(50354944, 'Gaia the Fierce Knight Origin', '暗黑骑士盖亚本源', '暗黒騎士ガイアオリジン', 'Effect Monster', 'Warrior', 'EARTH', 4, 1600, 1200, '这个卡名的①③的效果1回合各能使用1次。 ①：从手卡把1只5星以上的怪兽送去墓地才能发动。这张卡从手卡特殊召唤。 ②：战士族怪兽上级召唤的场合，这张卡可以作为2只的数量解放。 ③：自己·对方的战斗阶段，把墓地的这张卡除外，以持有和原本攻击力不同攻击力的场上1只怪兽为对象才能发动。那只怪兽的攻击力变成原本数值。'),
(34130561, 'Gaia the Magical Knight', '魔道骑士盖亚', '魔道騎士ガイア', 'Effect Monster', 'Warrior', 'LIGHT', 7, 2300, 2100, '这个卡名在规则上也当作「暗黑骑士 盖亚」卡使用。这个卡名的②的效果1回合只能使用1次。 ①：自己场上没有怪兽存在的场合或者对方场上有攻击力2300以上的怪兽存在的场合，这张卡可以不用解放作召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从自己的手卡·墓地选1只龙族·5星怪兽守备表示特殊召唤。'),
(15989522, 'Gaia the Magical Knight of Dragons', '龙魔道骑士盖亚', '竜魔道騎士ガイア', 'Fusion Monster', 'Dragon', 'WIND', 7, 2600, 2100, '「暗黑骑士 盖亚」怪兽＋5星龙族怪兽 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡只要在怪兽区域存在，卡名当作「龙骑士 盖亚」使用。 ②：自己·对方的主要阶段，以这张卡以外的场上1张卡为对象才能发动。这张卡的攻击力下降2600，作为对象的卡破坏。 ③：这张卡战斗破坏对方怪兽时才能发动。这张卡的攻击力上升2600。'),
(40371092, 'Gaia, the Mid-Knight Sun', '白夜之骑士 盖亚', '白夜の騎士ガイア', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1600, 1200, '「白夜之骑士 盖亚」的以下效果1回合各能使用1次。 ●把这张卡以外的自己场上1只光属性怪兽解放才能发动。从卡组把1只战士族·暗属性·4星怪兽加入手卡，那之后1张手卡送去墓地。 ●把自己墓地1只暗属性怪兽除外，选择场上1只怪兽才能发动。选择的怪兽的攻击力直到对方的结束阶段时下降500。'),
(14882493, 'Gaia, the Polar Knight', '极夜之骑士 盖亚', '極夜の騎士ガイア', 'Effect Monster', 'Warrior', 'DARK', 4, 1600, 1200, '「极夜之骑士 盖亚」的以下效果1回合各能使用1次。 ●把这张卡以外的自己场上1只暗属性怪兽解放才能发动。从卡组把1只战士族·光属性·4星怪兽加入手卡，那之后1张手卡送去墓地。 ●把自己墓地1只光属性怪兽除外，选择自己场上1只怪兽才能发动。选择的怪兽的攻击力直到对方的结束阶段时上升500。'),
(49816630, 'Gaiarmor Dragonshell', '甲缠龙 盖亚甲胄', '甲纏竜ガイアーム', 'Synchro Monster', 'Dragon', 'EARTH', 6, 2000, 1300, '调整＋调整以外的怪兽1只以上 这个卡名的①②③的效果1回合各能使用1次。 ①：把这张卡解放，以这张卡以外的自己墓地3只同调怪兽为对象才能发动。那些怪兽回到额外卡组。 ②：以从额外卡组特殊召唤的自己场上1只怪兽为对象才能发动。墓地的这张卡当作装备卡使用给那只怪兽装备。 ③：有这张卡装备的怪兽进行战斗的攻击宣言时才能发动。自己从卡组抽1张。'),
(20349913, 'Galactic Charity', '银河的施舍', '銀河の施し', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有名字带有「银河」的超量怪兽存在的场合，丢弃1张手卡才能发动。从卡组抽2张卡。这张卡发动过的回合，对方受到的全部伤害变成一半。「银河的施舍」在1回合只能发动1张。'),
(88774734, 'Galactic Spiral Dragon', '螺旋龙 核球', '螺旋竜バルジ', 'Effect Monster', 'Dragon', 'DARK', 8, 2500, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，自己场上有光·暗属性的龙族怪兽2只以上存在的场合才能发动。这张卡守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：自己主要阶段才能发动。自己场上的全部怪兽的等级直到回合结束时变成8星。'),
(46261704, 'Galactikuriboh', '盖勒库里波', 'ギャラクリボー', 'Effect Monster', 'Fiend', 'LIGHT', 1, 300, 200, '①：对方怪兽的攻击宣言时，把这张卡从手卡丢弃才能发动。从手卡·卡组把1只「银河眼光子龙」特殊召唤。那之后，攻击对象转移为那只怪兽。并且，可以再选自己或者对方场上1只超量怪兽把墓地的这张卡在那只怪兽下面重叠作为超量素材。 ②：自己场上的「光子」怪兽或者「银河」怪兽被战斗或者对方的效果破坏的场合，可以作为代替把墓地的这张卡除外。'),
(48835607, 'Galatea-I, the Orcust Automaton', '自鸣天琴・伽拉忒亚i', 'オルフェゴール・ガラテアi', 'Link Monster', 'Machine', 'DARK', NULL, NULL, NULL, '「自奏圣乐」怪兽或「星遗物」怪兽1只 自己对「自奏圣乐·伽拉忒亚i」1回合只能有1次连接召唤。这张卡不能作为超量召唤的素材。这个卡名的①②的效果1回合各能使用1次。 ①：把1张手卡送去墓地才能发动。从自己的卡组·墓地把1只「星遗物」怪兽或1张「自奏圣乐的通天塔」加入手卡。 ②：这张卡在墓地存在的场合，从自己墓地把1张其他的「自奏圣乐」卡除外才能发动。这张卡特殊召唤。'),
(30741503, 'Galatea, the Orcust Automaton', '自鸣天琴・伽拉忒亚', 'オルフェゴール・ガラテア', 'Link Monster', 'Machine', 'DARK', NULL, 1800, NULL, '包含「自奏圣乐」怪兽的效果怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：连接状态的这张卡不会被战斗破坏。 ②：以自己的除外状态的1只机械族怪兽为对象才能发动。那只怪兽回到卡组。那之后，可以从卡组把1张「自奏圣乐」魔法·陷阱卡在自己场上盖放。'),
(55168550, 'Galaxy Brave', '银河剑圣', '銀河剣聖', 'Effect Monster', 'Warrior', 'LIGHT', 8, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡1只「光子」怪兽给对方观看才能发动。这张卡从手卡特殊召唤。这张卡的等级变成和给人观看的「光子」怪兽的等级相同。 ②：这张卡召唤·特殊召唤成功的场合，以自己墓地1只「银河」怪兽为对象才能发动。这张卡的攻击力·守备力变成和那只怪兽的各自数值相同。'),
(28770951, 'Galaxy Cleric', '银河修道师', '銀河の修道師', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1500, 600, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1只「光子」超量怪兽或者「银河」超量怪兽为对象才能发动。把手卡的这张卡在那只怪兽下面重叠作为超量素材。 ②：这张卡召唤·特殊召唤成功的场合，从自己墓地的「光子」卡以及「银河」卡之中以合计5张为对象才能发动（同名卡最多1张）。那些卡加入卡组洗切。那之后，自己从卡组抽2张。'),
(5133471, 'Galaxy Cyclone', '银河气旋', 'ギャラクシー・サイクロン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以场上1张里侧表示的魔法·陷阱卡为对象才能发动。那张卡破坏。 ②：把这个回合没有送去墓地的这张卡从墓地除外，以场上1张表侧表示的魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(9024367, 'Galaxy Dragon', '银河龙骑士', 'ギャラクシー・ドラグーン', 'Effect Monster', 'Dragon', 'LIGHT', 4, 2000, 1200, '①：这张卡不能直接攻击，只能向龙族怪兽攻击。 ②：这张卡和龙族怪兽进行战斗的场合，只在战斗阶段内那只怪兽的效果无效化，只在伤害步骤内这张卡的攻击力上升1000。'),
(60222582, 'Galaxy Expedition', '银河远征', '銀河遠征', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有5星以上的，「光子」怪兽或「银河」怪兽存在的场合才能发动。从卡组把5星以上的1只「光子」怪兽或「银河」怪兽守备表示特殊召唤。'),
(897409, 'Galaxy Hundred', '银河百式', '銀河百式', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1张「光子」卡或「银河」卡送去墓地。 ②：自己场上有「银河眼光子龙」特殊召唤的场合才能发动。把对方的额外卡组确认。那之后，可以从以下效果让1个适用。 ●那之内的1只怪兽除外。 ●那之内的1只「No.」怪兽在自己场上特殊召唤。'),
(79509511, 'Galaxy Journey', '银河超航行', '銀河超航行', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的除外状态的1只光·暗属性怪兽特殊召唤。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的超量怪兽被除外的场合，把这张卡除外，以那之内的1只为对象才能发动。那只怪兽特殊召唤。'),
(35950025, 'Galaxy Knight', '银河骑士', '銀河騎士', 'Effect Monster', 'Warrior', 'LIGHT', 8, 2800, 2600, '①：自己场上有「光子」怪兽或者「银河」怪兽存在的场合，这张卡可以不用解放作召唤。 ②：这张卡的①的方法召唤成功的场合，以自己墓地1只「银河眼光子龙」为对象发动。这张卡的攻击力直到回合结束时下降1000，作为对象的怪兽守备表示特殊召唤。'),
(98263709, 'Galaxy Mirror Sage', '银河魔镜士', '銀河魔鏡士', 'Flip Effect Monster', 'Spellcaster', 'LIGHT', 3, NULL, 800, '反转：自己回复自己墓地的名字带有「银河」的怪兽数量×500基本分。此外，反转过的这张卡被破坏送去墓地时，可以从自己的卡组·墓地选1只4星以下的名字带有「银河」的怪兽里侧守备表示特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合从游戏中除外。'),
(85747929, 'Galaxy Photon Dragon', '银河光子龙', '銀河光子竜', 'XYZ Monster', 'Dragon', 'LIGHT', 4, 2000, NULL, '4星怪兽×2 这个卡名的②③的效果1回合各能使用1次。 ①：自己场上的其他的光属性怪兽的攻击力上升500。 ②：把这张卡1个超量素材取除才能发动。从卡组选1张「光子」卡或「银河」卡加入手卡或送去墓地。 ③：自己场上有光属性怪兽特殊召唤的场合，以那之内的1只为对象才能发动。那只怪兽的等级直到回合结束时变成4星或8星。'),
(52340274, 'Galaxy Queen''s Light', '银河女王之光', 'ギャラクシー・クィーンズ・ライト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只7星以上的怪兽为对象才能发动。自己场上的全部怪兽的等级直到回合结束时变成和作为对象的怪兽相同等级。'),
(92362073, 'Galaxy Satellite Dragon', '银河卫龙', '銀河衛竜', 'Link Monster', 'Dragon', 'DARK', NULL, 2000, NULL, '龙族怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的战斗阶段，把场上·墓地的这张卡除外，以自己场上1只原本的种族·属性是龙族·光属性的「No.」超量怪兽为对象才能发动。直到战斗阶段结束时，对方受到的战斗伤害变成一半，作为对象的怪兽的攻击力变成那只怪兽持有的「No.」数值×100。 ②：对方结束阶段才能发动。从卡组选1张卡在卡组最上面放置。'),
(11066358, 'Galaxy Serpent', '银河长蛇', 'ギャラクシーサーペント', 'Normal Tuner Monster', 'Dragon', 'LIGHT', 2, 1000, NULL, '据说会趁着暮色现形的龙。因飞行时犹如畅泳星海这神秘身姿而得其名。虽说相传目睹其姿容者是寥寥可数，不过据说有幸目睹者能得到新力量。'),
(46659709, 'Galaxy Soldier', '银河战士', '銀河戦士', 'Effect Monster', 'Machine', 'LIGHT', 5, 2000, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：从手卡把1只其他的光属性怪兽送去墓地才能发动。这张卡从手卡守备表示特殊召唤。 ②：这张卡特殊召唤时才能发动。从卡组把1只「银河」怪兽加入手卡。'),
(54358015, 'Galaxy Stealth Dragon', '银河影龙', '銀河影竜', 'XYZ Monster', 'Dragon', 'DARK', 4, 2000, 1600, '龙族4星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。从手卡把1只龙族怪兽特殊召唤。 ②：只要这张卡在怪兽区域存在，这张卡以外的自己场上的「银河」卡不会成为对方的效果的对象，不会被对方的效果破坏。'),
(80887714, 'Galaxy Storm', '银河风暴', 'ギャラクシー・ストーム', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择场上存在的1只没有超量素材的超量怪兽破坏。'),
(863795, 'Galaxy Summoner', '银河召唤师', '銀河の召喚師', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 1600, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，以「银河召唤师」以外的自己墓地1只「光子」怪兽或「银河」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。 ②：以自己场上1只其他的光属性怪兽为对象才能发动。那只怪兽的等级直到回合结束时变成4星。'),
(63956833, 'Galaxy Trance', '银河天翔', '銀河天翔', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是「光子」怪兽以及「银河」怪兽不能召唤·特殊召唤。 ①：支付2000基本分，以自己墓地1只「光子」怪兽为对象才能发动。把持有和那只怪兽相同等级的卡组1只「银河」怪兽和作为对象的墓地的怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的攻击力变成2000，效果无效化。'),
(24658418, 'Galaxy Tyranno', '银河暴龙', '銀河暴竜', 'Effect Monster', 'Dinosaur', 'LIGHT', 8, 2000, NULL, '自己场上的名字带有「银河」的怪兽被选择作为攻击对象时才能发动。这张卡从手卡表侧守备表示特殊召唤。这个效果特殊召唤成功时，可以只用自己场上的名字带有「银河」的怪兽为素材，把1只名字带有「银河」的超量怪兽超量召唤。'),
(19316241, 'Galaxy War Drake', '银河战龙', '銀河戦竜', 'Effect Monster', 'Dragon', 'LIGHT', 4, 1500, 1000, '这个卡名的①②的效果1回合各能使用1次，这些效果发动的回合，自己不是光属性怪兽不能特殊召唤。 ①：自己场上有光属性·4星怪兽特殊召唤的场合才能发动。这张卡从手卡·墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：以自己场上1只其他的光属性·4星怪兽为对象才能发动。那只怪兽和这张卡的等级直到回合结束时变成8星。'),
(77098449, 'Galaxy Wave', '银河波动', 'ギャラクシー・ウェーブ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每次自己超量召唤成功，给与对方基本分500分伤害。'),
(98555327, 'Galaxy Wizard', '银河魔导师', '銀河の魔導師', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, NULL, 1800, '①：1回合1次，自己主要阶段才能发动。这张卡的等级直到回合结束时上升4星。 ②：把这张卡解放才能发动。从卡组把「银河魔导师」以外的1张「银河」卡加入手卡。'),
(54507222, 'Galaxy Worm', '银河异虫', 'ギャラクシー・ワーム', 'Effect Monster', 'Insect', 'LIGHT', 3, 1200, 1000, '①：这张卡召唤成功时，自己场上没有这张卡以外的怪兽存在的场合才能发动。从卡组把1只3星以下的「银河」效果怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(97617181, 'Galaxy Zero', '银河零式', '銀河零式', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「银河零式」在1回合只能发动1张。 ①：以自己墓地1只「光子」怪兽或者「银河」怪兽为对象才能把这张卡发动。那只怪兽攻击表示特殊召唤，把这张卡装备。装备怪兽不能攻击，效果也不能发动。 ②：装备怪兽在战斗阶段被战斗·效果破坏的场合，可以作为代替把这张卡破坏。 ③：表侧表示的这张卡从场上离开的场合发动。这张卡装备过的怪兽的攻击力变成0。'),
(62968263, 'Galaxy-Eyes Afterglow Dragon', '银河眼残光龙', '銀河眼の残光竜', 'Effect Monster', 'Dragon', 'LIGHT', 8, 3000, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「银河眼」怪兽存在的场合才能发动。这张卡从手卡守备表示特殊召唤。 ②：超量素材的这张卡为让超量怪兽的效果发动而被取除的场合才能发动。从手卡·卡组选1只「银河眼光子龙」特殊召唤或在自己的超量怪兽下面重叠作为超量素材。这个效果在战斗阶段发动的场合，再让自己场上的全部「No.」超量怪兽的攻击力变成2倍。'),
(92517928, 'Galaxy-Eyes Antimatter Dragon', '银河眼反物质龙', 'ギャラクシーアイズ・アンチマター・ドラゴン', 'XYZ Monster', 'Dragon', 'LIGHT', 9, 4000, NULL, '9星怪兽×2 「银河眼反物质龙」1回合1次也能在持有超量素材3个以上的自己的超量怪兽上面重叠来超量召唤。 ①：持有超量素材的这张卡给与对方的战斗伤害变成一半。 ②：把这张卡1个超量素材取除才能发动。这个回合，这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。取除的超量素材是怪兽的场合，可以再把和那只怪兽相同种族的1只怪兽从卡组送去墓地。'),
(2530830, 'Galaxy-Eyes Cipher Blade Dragon', '银河眼光波刃龙', '銀河眼の光波刃竜', 'XYZ Monster', 'Dragon', 'LIGHT', 9, 3200, 2800, '9星怪兽×3 这张卡也能在自己场上的8阶「银河眼」超量怪兽上面重叠来超量召唤。这张卡不能作为超量召唤的素材。 ①：1回合1次，把这张卡1个超量素材取除，以场上1张卡为对象才能发动。那张卡破坏。 ②：超量召唤的这张卡被对方怪兽的攻击或者对方的效果破坏送去墓地的场合，以自己墓地1只「银河眼光波龙」为对象才能发动。那只怪兽特殊召唤。'),
(18963306, 'Galaxy-Eyes Cipher Dragon', '银河眼光波龙', '銀河眼の光波竜', 'XYZ Monster', 'Dragon', 'LIGHT', 8, 3000, 2500, '8星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。这个效果得到控制权的怪兽的效果无效化，攻击力变成3000，卡名当作「银河眼光波龙」使用。这个效果的发动后，直到回合结束时这张卡以外的自己怪兽不能直接攻击。'),
(28346136, 'Galaxy-Eyes Cipher X Dragon', '银河眼光波极龙', '銀河眼の極光波竜', 'XYZ Monster', 'Dragon', 'LIGHT', 10, 4000, 3000, '10星怪兽×2 「银河眼极光波龙」1回合1次也能在自己场上的「光波龙」怪兽上面重叠来超量召唤。 ①：把这张卡2个超量素材取除才能发动。自己场上的光属性怪兽直到对方回合结束时不会成为对方的效果的对象。 ②：自己准备阶段才能发动。自己墓地1只9阶以下的龙族超量怪兽回到额外卡组。那之后，可以把那只怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤。'),
(9260791, 'Galaxy-Eyes Cloudragon', '银河眼云笼', '銀河眼の雲篭', 'Effect Monster', 'Dragon', 'LIGHT', 1, 300, 250, '把这张卡解放才能发动。从自己的手卡·墓地选「银河眼云笼」以外的1只名字带有「银河眼」的怪兽特殊召唤。「银河眼云笼」的这个效果1回合只能使用1次。此外，这张卡在墓地存在的场合，自己的主要阶段时选择自己场上1只名字带有「银河眼」的超量怪兽才能发动。把墓地的这张卡在选择的怪兽下面重叠作为超量素材。「银河眼云笼」的这个效果在决斗中只能使用1次。'),
(39030163, 'Galaxy-Eyes Full Armor Photon Dragon', '银河眼全装甲光子龙', 'ギャラクシーアイズ FA・フォトン・ドラゴン', 'XYZ Monster', 'Dragon', 'LIGHT', 8, 4000, 3500, '8星怪兽×3 这张卡也能在「银河眼重铠光子龙」以外的自己场上的「银河眼」超量怪兽上面重叠来超量召唤。 ①：1回合1次，以这张卡最多2张装备卡为对象才能发动。那些卡在这张卡下面重叠作为超量素材。 ②：1回合1次，把这张卡1个超量素材取除，以对方场上1张表侧表示的卡为对象才能发动。那张卡破坏。'),
(93717133, 'Galaxy-Eyes Photon Dragon', '银河眼光子龙', '銀河眼の光子竜', 'Effect Monster', 'Dragon', 'LIGHT', 8, 3000, 2500, '①：这张卡可以把自己场上2只攻击力2000以上的怪兽解放从手卡特殊召唤。 ②：这张卡和对方怪兽进行战斗的战斗步骤，以那1只对方怪兽为对象才能发动。那只对方怪兽和场上的这张卡除外。这个效果除外的怪兽在战斗阶段结束时回到场上，这个效果把超量怪兽除外的场合，这张卡的攻击力上升把那只超量怪兽除外时的超量素材数量×500。'),
(3356494, 'Galaxy-Eyes Solflare Dragon', '银河眼煌星龙', '銀河眼の煌星竜', 'Link Monster', 'Dragon', 'LIGHT', NULL, 2000, NULL, '包含攻击力2000以上的怪兽的光属性怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤成功的场合，以自己墓地1只「光子」怪兽或者「银河」怪兽为对象才能发动。那只怪兽加入手卡。 ②：对方主要阶段，把「光子」卡和「银河」卡共2张或者「银河眼光子龙」1只从手卡丢弃，以对方场上1只特殊召唤的怪兽为对象才能发动。那只怪兽破坏。'),
(45710945, 'Galaxy-Eyes Tachyon Primal', '银河眼时空源龙', '銀河眼の時源竜', 'Effect Monster', 'Dragon', 'LIGHT', 8, 3000, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，场上有龙族超量怪兽存在的场合才能发动。这张卡从手卡往自己或对方的场上特殊召唤。 ②：这张卡召唤·特殊召唤的场合发动。这张卡的原本持有者从自身卡组把1张「时空」魔法·陷阱卡加入手卡。 ③：自己或对方的龙族超量怪兽的攻击宣言时发动。把场上的这张卡作为那只怪兽的超量素材。'),
(16229315, 'Gale Dogra', '疾风毒蛾', 'ゲール・ドグラ', 'Effect Monster', 'Insect', 'EARTH', 2, 650, 600, '①：支付3000基本分才能发动。从自己的额外卡组把1只怪兽送去墓地。'),
(77491079, 'Gale Lizard', '爆风蜥蜴', '爆風トカゲ', 'Flip Effect Monster', 'Reptile', 'WATER', 4, 1400, 700, '①：这张卡反转的场合，以对方场上1只怪兽为对象发动。那只对方怪兽回到持有者手卡。'),
(32530043, 'Gallant Granite', '御影志士', '御影志士', 'XYZ Monster', 'Rock', 'EARTH', 4, 2300, 1800, '4星怪兽×2 这个卡名的效果1回合只能使用1次。 ①：可以把这张卡1个超量素材取除，从以下效果选择1个发动。 ●从卡组把1只岩石族怪兽加入手卡。 ●从手卡把1只岩石族怪兽里侧守备表示特殊召唤。'),
(30915572, 'Gallis the Star Beast', '星见兽 加里斯', '星見獣ガリス', 'Effect Monster', 'Beast', 'EARTH', 3, 800, 800, '把手卡的这张卡给对方观看发动。自己卡组最上面的卡送去墓地，那张卡是怪兽的场合，给与对方基本分那只怪兽的等级×200的数值的伤害并把这张卡特殊召唤。那张卡是怪兽以外的场合，这张卡破坏。'),
(2106266, 'Galloping Gaia', '奔驰到底的盖亚', '走破するガイア', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：只要自己的怪兽区域有「龙骑士 盖亚」存在，对方在战斗阶段中不能把效果发动。 ②：可以从以下效果选择1个发动。 ●把手卡1只「暗黑骑士 盖亚」怪兽给对方观看才能发动。从卡组把1只龙族·5星怪兽加入手卡。 ●把手卡1只龙族·5星怪兽给对方观看才能发动。从卡组把1只「暗黑骑士 盖亚」怪兽加入手卡。'),
(37313786, 'Gamble', '赌博', 'ギャンブル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方的手卡6张以上，自己的手卡2张以下的时候才可以发动。猜硬币的正反。 ●猜中：自己的手卡抽到5张。 ●猜不中：跳过下次的自己的整个回合。'),
(2196767, 'Gambler of Legend', '传说的赌博师', '伝説の賭博師', 'Effect Monster', 'Spellcaster', 'DARK', 4, 500, 1400, '进行3次投掷硬币。 ●3次都是表的场合，对方场上怪兽全部破坏。 ●2次表的场合，对方手卡随机丢弃1张。 ●1次表的场合，自己场上存在的1张卡破坏。 ●3次都是里的场合，自己手卡全部丢弃。 这个效果1回合只有1次在自己的主要阶段才能使用。'),
(55063751, 'Gameciel, the Sea Turtle Kaiju', '海龟坏兽加美希尔', '海亀壊獣ガメシエル', 'Effect Monster', 'Aqua', 'WATER', 8, 2200, 3000, '①：这张卡可以把对方场上1只怪兽解放，从手卡往对方场上攻击表示特殊召唤。 ②：对方场上有「坏兽」怪兽存在的场合，这张卡可以从手卡攻击表示特殊召唤。 ③：「坏兽」怪兽在自己场上只能有1只表侧表示存在。 ④：对方把「海龟坏兽 加美西耶勒」以外的魔法·陷阱·怪兽的效果发动时，把自己·对方场上2个坏兽指示物取除才能发动。那个发动无效并除外。'),
(15502037, 'Gamma The Electromagnet Warrior', '电磁石战士伽玛', '電磁石の戦士γ', 'Effect Monster', 'Rock', 'EARTH', 3, 800, 2000, '「电磁石战士γ」的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从手卡把「电磁石战士γ」以外的1只4星以下的「磁石战士」怪兽特殊召唤。 ②：对方回合把这张卡解放才能发动。从卡组把1只4星「磁石战士」怪兽特殊召唤。'),
(11549357, 'Gamma the Magnet Warrior', '磁石战士伽玛', '磁石の戦士γ', 'Normal Monster', 'Rock', 'EARTH', 4, 1500, 1800, '用α、β、γ来变形合体。'),
(85709845, 'Gamushara', '有勇无谋', 'ガムシャラ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上守备表示存在的怪兽成为攻击对象时才能发动。那只守备表示怪兽的表示形式变更为表侧攻击表示。并且，那次战斗破坏攻击怪兽送去墓地时，再给与对方基本分那只怪兽的原本攻击力数值的伤害。'),
(24291651, 'Ganbara Knight', '加把劲骑士', 'ガンバラナイト', 'Effect Monster', 'Warrior', 'LIGHT', 4, NULL, 1800, '场上表侧攻击表示存在的这张卡被选择作为攻击对象时，可以把这张卡的表示形式变成守备表示。'),
(65758454, 'Ganbara Lancer', '加把劲枪兵', 'ガンバランサー', 'Effect Monster', 'Warrior', 'LIGHT', 5, 1000, 2000, '这张卡召唤成功时，可以从自己的手卡·墓地选1只「加把劲枪兵」表侧守备表示特殊召唤。'),
(64681432, 'Gandora the Dragon of Destruction', '破坏龙 钢多拉', '破壊竜ガンドラ', 'Effect Monster', 'Dragon', 'DARK', 8, NULL, NULL, '这张卡不能特殊召唤。 ①：把基本分支付一半才能发动。场上的其他卡全部破坏并除外。这张卡的攻击力上升这个效果破坏的卡数量×300。 ②：这张卡召唤·反转召唤的回合的结束阶段发动。这张卡送去墓地。'),
(2333466, 'Gandora-G the Dragon of Destruction', '破坏龙 钢多拉G', '破壊竜ガンドラG', 'Effect Monster', 'Dragon', 'DARK', 8, NULL, NULL, '这个卡名的①③的效果1回合各能使用1次。 ①：自己场上有「光之黄金柜」存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡的攻击力上升除外状态的卡数量×300。 ③：把基本分支付一半才能发动。场上的其他卡全部破坏并除外。那之后，从卡组把有「光之黄金柜」的卡名记述的1只7星以下的怪兽特殊召唤。这个效果特殊召唤的怪兽的等级上升这个效果破坏的卡数量的数值。'),
(71525232, 'Gandora-X the Dragon of Demolition', '破灭龙 钢多拉X', '破滅竜ガンドラX', 'Effect Monster', 'Dragon', 'DARK', 8, NULL, NULL, '①：这张卡从手卡召唤·特殊召唤时才能发动。场上的其他怪兽全部破坏，给与对方破坏的怪兽之内原本攻击力最高的怪兽的那个数值的伤害。这张卡的攻击力变成和这个效果给与对方的伤害相同数值。 ②：自己结束阶段发动。自己基本分变成一半。'),
(34536276, 'Ganigumo', '蟹蛛', 'ガニグモ', 'Normal Monster', 'Insect', 'EARTH', 2, 600, 800, '长有钳子的蜘蛛。用蜘蛛丝封住对方的动作用螃蟹钳子杀死对方。'),
(11801343, 'Garbage Collector', '垃圾收集员', 'ガベージコレクター', 'Effect Monster', 'Cyberse', 'WIND', 2, 100, 1900, '这个卡名的效果1回合只能使用1次。 ①：以这张卡以外的自己场上1只电子界族怪兽为对象才能发动。那只怪兽回到持有者手卡，和回到手卡的怪兽相同等级而卡名不同的1只电子界族怪兽从卡组特殊召唤。'),
(44682448, 'Garbage Lord', '垃圾王', 'ガーベージ・ロード', 'Effect Monster', 'Fiend', 'DARK', 5, NULL, 2400, '这张卡可以支付2000基本分，从手卡特殊召唤。把这张卡作为超量素材的场合，不是暗属性怪兽的超量召唤不能使用。'),
(18698739, 'Garbage Ogre', '垃圾食人魔', 'ガーベージ・オーガ', 'Effect Monster', 'Fiend', 'DARK', 3, 800, 1300, '自己的主要阶段时，把这张卡从手卡送去墓地才能发动。从卡组把1只「垃圾王」加入手卡。「垃圾食人魔」的效果1回合只能使用1次。'),
(76524506, 'Garden Rose Flora', '花园蔷薇芙萝拉', 'ガーデン・ローズ・フローラ', 'Synchro Tuner Monster', 'Plant', 'LIGHT', 5, 800, 1600, '调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：以场上1张场地魔法卡为对象才能发动。那张卡破坏。那之后，在那个控制者场上把1只「蔷薇衍生物」（植物族·暗·2星·攻/守800）攻击表示特殊召唤。这个回合，自己不是同调怪兽不能从额外卡组特殊召唤。 ②：对方主要阶段才能发动。用包含这张卡的自己场上的怪兽为素材作同调召唤。'),
(53325667, 'Garden Rose Maiden', '花园蔷薇少女', 'ガーデン・ローズ・メイデン', 'Synchro Monster', 'Plant', 'DARK', 5, 1600, 2400, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从自己的卡组·墓地把1张「黑色花园」加入手卡。 ②：把墓地的这张卡除外，以自己墓地1只「蔷薇龙」怪兽或龙族同调怪兽为对象才能发动。那只怪兽特殊召唤。'),
(32872239, 'Gargardo the Necroforger Fiend', '加尔加尔德炼尸魔', 'ガルガルドの屍煉魔', 'Pendulum Normal Monster', 'Fiend', 'FIRE', 6, 2000, 2000, '身披摇荡之炎，能变一切他者之貌的鸟魔人。从鸟到人、从人到鸟反复变化的过程中，就这么遗忘了本来的自己。'),
(30646525, 'Garlandolf, King of Destruction', '破灭之魔王 加兰道夫', '破滅の魔王ガーランドルフ', 'Ritual Effect Monster', 'Fiend', 'DARK', 7, 2500, 1400, '「破灭的仪式」降临。这张卡仪式召唤成功时，持有这张卡的攻击力以下的守备力的这张卡以外的场上表侧表示存在的怪兽全部破坏，破坏的怪兽每有1只这张卡的攻击力上升100。'),
(90844184, 'Garma Sword', '伽玛剑', 'ガルマソード', 'Ritual Monster', 'Warrior', 'DARK', 7, 2550, 2150, '「伽玛剑的誓言」降临。'),
(78577570, 'Garma Sword Oath', '伽玛剑的誓言', 'ガルマソードの誓い', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「伽玛剑」的降临必需。 ①：从自己的手卡·场上把等级合计直到7以上的怪兽解放，从手卡把1只「伽玛剑」仪式召唤。'),
(88283496, 'Garmr of the Nordic Beasts', '极星兽 加尔姆', '極星獣ガルム', 'Effect Monster', 'Beast', 'DARK', 4, 800, 1900, '这张卡和4星以下的怪兽进行战斗的伤害计算后，可以让那只怪兽回到手卡。'),
(49888191, 'Garnecia Elefantis', '甘尼许巨象', 'ガーネシア・エレファンティス', 'Normal Monster', 'Beast-Warrior', 'EARTH', 7, 2400, 2000, '拥有可怕的力量，因体形臃肿，行走时会发生地震。'),
(14977074, 'Garoozis', '加鲁撒斯', 'ガルーザス', 'Normal Monster', 'Beast-Warrior', 'FIRE', 5, 1800, 1500, '长有龙头的兽战士，斧头具有相当大的威力。'),
(59019082, 'Garoth, Lightsworn Warrior', '光道战士 伽罗斯', 'ライトロード・ウォリアー ガロス', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1850, 1300, '「光道战士 加洛斯」以外的自己场上的名字带有「光道」的怪兽的效果从自己卡组让卡送去墓地的场合，从自己卡组上面把2张卡送去墓地。那之后，从卡组抽出这个效果送去墓地的名字带有「光道」的怪兽数量的卡。'),
(12800777, 'Garuda the Wind Spirit', '风之精灵 迦楼罗', '風の精霊 ガルーダ', 'Effect Monster', 'Winged Beast', 'WIND', 4, 1600, 1200, '这张卡不能通常召唤。从自己墓地把1只风属性怪兽除外的场合可以特殊召唤。 ①：对方结束阶段，以对方场上1只表侧表示怪兽为对象才能发动。那只对方的表侧表示怪兽的表示形式变更。'),
(22382087, 'Garum the Storm Vassal', '风帝家臣迦楼姆', '風帝家臣ガルーム', 'Effect Monster', 'Winged Beast', 'WIND', 3, 800, 1000, '「风帝家臣 迦楼姆」的①②的效果1回合各能使用1次。 ①：让自己场上1只上级召唤的怪兽回到持有者手卡才能发动。这张卡从手卡特殊召唤。这个回合，自己不能从额外卡组把怪兽特殊召唤。 ②：这张卡为上级召唤而被解放的场合才能发动。从卡组把「风帝家臣 迦楼姆」以外的1只攻击力800/守备力1000的怪兽加入手卡。'),
(64182380, 'Garunix Eternity, Hyang of the Fire Kings', '炎王神 迦楼多尼克斯・永炎', '炎王神 ガルドニクス・エタニティ', 'XYZ Monster', 'Pyro', 'FIRE', 8, 3000, 2000, '8星怪兽×2只以上 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡超量召唤的场合才能发动。场上的其他怪兽全部破坏。 ②：把这张卡1个超量素材取除，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏，这张卡的攻击力上升500。 ③：持有超量素材的这张卡被破坏的场合才能发动。把最多有这张卡持有的超量素材数量的「炎王」怪兽从自己墓地特殊召唤。'),
(11765832, 'Garura, Wings of Resonant Life', '共命之翼 迦楼拉', '共命の翼ガルーラ', 'Fusion Monster', 'Winged Beast', 'DARK', 6, 1500, 2400, '相同种族·属性而卡名不同的怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：这张卡的战斗发生的对对方的战斗伤害变成2倍。 ②：这张卡被送去墓地的场合才能发动。自己抽1张。'),
(69780745, 'Garvas', '加尔瓦斯', 'ガルヴァス', 'Normal Monster', 'Beast', 'EARTH', 6, 2000, 1700, '恶之化身。样子如同长着羽毛的狮子。'),
(19012345, 'Gash the Dust Lord', '灰尘王 灰划', '灰塵王 アッシュ・ガッシュ', 'Effect Monster', 'Fiend', 'DARK', 4, 1000, 1200, '这张卡给与对方基本分战斗伤害时，这张卡的等级上升1星（等级最多12星）。'),
(39475024, 'Gashadokuro, the Skeletal Mayakashi', '骸之魔妖－饿者髑髅', '骸の魔妖－餓者髑髏', 'Synchro Monster', 'Zombie', 'DARK', 11, 3300, 2600, '调整＋调整以外的怪兽1只以上 这个卡名的②③的效果1回合各能使用1次。 ①：「骸之魔妖-饿者髑髅」在自己场上只能有1只表侧表示存在。 ②：这张卡在墓地存在，自己的连接怪兽被战斗或者对方的效果破坏的场合才能发动。从自己墓地把1只其他的不死族怪兽除外，这张卡特殊召唤。 ③：这张卡从墓地的特殊召唤成功的场合才能发动。这个回合，表侧表示的这张卡不受其他卡的效果影响。'),
(82257671, 'Gatchiri @Ignister', '坚盾固固＠伊格尼斯者', 'ガッチリ＠イグニスター', 'Effect Monster', 'Cyberse', 'EARTH', 8, NULL, 3000, '这个卡名的①③的效果1回合各能使用1次。 ①：以自己场上1只电子界族效果怪兽为对象才能发动。那只怪兽的效果无效，这张卡从手卡特殊召唤。 ②：自己场上的电子界族怪兽在1回合各有1次不会被效果破坏。 ③：这张卡从场上送去墓地的场合，以自己场上1只表侧表示怪兽为对象才能发动。那只自己的表侧表示怪兽直到对方回合结束时不受对方的效果影响。'),
(8102334, 'Gate Blocker', '门之防壁', 'ゲート・ブロッカー', 'Effect Monster', 'Rock', 'EARTH', 4, 100, 2000, '①：只要这张卡在怪兽区域存在，对方不能把其他的自己场上的怪兽作为效果的对象，不能给场上的卡放置指示物。此外，对方的场地魔法卡的效果无效。'),
(49258578, 'Gate Deeg', '地狱之门', 'ヘルゲート・ディーグ', 'Normal Monster', 'Beast', 'DARK', 3, 700, 800, '肚子上长着通向地狱的门，也可以被召唤的怪兽。'),
(25833572, 'Gate Guardian', '门之守护者', 'ゲート・ガーディアン', 'Effect Monster', 'Warrior', 'DARK', 11, 3750, 3400, '这张卡不能通常召唤。把自己场上的「雷魔神-桑迦」「风魔神-修迦」「水魔神-斯迦」各1只解放的场合可以特殊召唤。'),
(34904525, 'Gate Guardian of Thunder and Wind', '雷风魔神－门之守护者', '雷風魔神－ゲート・ガーディアン', 'Fusion Monster', 'Thunder', 'LIGHT', 9, 2500, 2200, '「雷魔神-桑迦」＋「风魔神-修迦」 把自己场上的上记的卡除外的场合才能特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段才能发动。把有「雷魔神-桑迦」「风魔神-修迦」「水魔神-斯迦」的卡名全部记述的1张魔法·陷阱卡从卡组加入手卡。 ②：特殊召唤的表侧表示的这张卡因对方从场上离开的场合才能发动。自己的除外状态的1只「雷魔神-桑迦」或「风魔神-修迦」特殊召唤。'),
(97783338, 'Gate Guardian of Water and Thunder', '水雷魔神－门之守护者', '水雷魔神－ゲート・ガーディアン', 'Fusion Monster', 'Aqua', 'WATER', 9, 2550, 2300, '「水魔神-斯迦」＋「雷魔神-桑迦」 把自己场上的上记的卡除外的场合才能特殊召唤。这个卡名的①的效果1回合可以使用最多2次。 ①：自己·对方回合，以对方场上1只表侧表示怪兽为对象才能发动（同一连锁上最多1次）。那只怪兽的攻击力直到回合结束时变成0。 ②：特殊召唤的表侧表示的这张卡因对方从场上离开的场合才能发动。自己的除外状态的1只「水魔神-斯迦」或「雷魔神-桑迦」特殊召唤。'),
(61398234, 'Gate Guardian of Wind and Water', '风水魔神－门之守护者', '風水魔神－ゲート・ガーディアン', 'Fusion Monster', 'Spellcaster', 'WIND', 9, 2450, 2300, '「风魔神-修迦」＋「水魔神-斯迦」 把自己场上的上记的卡除外的场合才能特殊召唤。这个卡名的①的效果1回合可以使用最多2次。 ①：对方把场上的魔法·陷阱卡的效果发动时才能发动（同一连锁上最多1次）。那个效果无效。 ②：特殊召唤的表侧表示的这张卡因对方从场上离开的场合才能发动。自己的除外状态的1只「风魔神-修迦」或「水魔神-斯迦」特殊召唤。'),
(8505920, 'Gate Guardians Combined', '合体魔神－门之守护者', '合体魔神－ゲート・ガーディアン', 'Fusion Monster', 'Warrior', 'DARK', 12, 3750, 3400, '「雷魔神-桑迦」＋「风魔神-修迦」＋「水魔神-斯迦」 把自己的手卡·场上·墓地的上记的卡除外的场合才能特殊召唤。这个卡名的①的效果1回合可以使用最多3次。 ①：自己场上的卡为对象的效果由对方发动时才能发动。那个效果无效并破坏。 ②：特殊召唤的表侧表示的这张卡因对方从场上离开的场合才能发动。从卡组·额外卡组把1只11星以下的「门之守护神」怪兽无视召唤条件特殊召唤。'),
(19737320, 'Gatekeeper', '看门人', 'ゲート・キーパー', 'Normal Monster', 'Machine', 'DARK', 5, 1500, 1800, '为守备王家墓地入口而造的机器。非常难以被破坏。'),
(91482773, 'Gateway Dragon', '网关龙', 'ゲートウェイ・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 4, 1600, 1400, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：对方场上有连接怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：1回合1次，自己主要阶段才能发动。从手卡把1只4星以下的龙族·暗属性怪兽特殊召唤。'),
(27970830, 'Gateway of the Six', '六武之门', '六武の門', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：每次「六武众」怪兽召唤·特殊召唤给这张卡放置2个武士道指示物。 ②：可以把自己场上的武士道指示物的以下数量取除，那个效果发动。 ●2个：以场上1只「六武众」效果怪兽或者「紫炎」效果怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升500。 ●4个：从自己的卡组·墓地选1只「六武众」怪兽加入手卡。 ●6个：以自己墓地1只「紫炎」效果怪兽为对象才能发动。那只怪兽特殊召唤。'),
(40089744, 'Gateway to Chaos', '混沌之场', '混沌の場', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，从卡组把1只「混沌战士」仪式怪兽或者「暗黑骑士 盖亚」怪兽加入手卡。 ②：只要这张卡在场地区域存在，每次从双方的手卡·场上有怪兽被送去墓地，每有1只给这张卡放置1个魔力指示物（最多6个）。 ③：1回合1次，把这张卡3个魔力指示物取除才能发动。自己从卡组把1张仪式魔法卡加入手卡。'),
(93431518, 'Gateway to Dark World', '连接暗黑界的结界通路', '暗黒界に続く結界通路', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能用这张卡的效果以外把怪兽召唤·反转召唤·特殊召唤。 ①：以自己墓地1只「暗黑界」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(7512044, 'Gather Your Mind', '精神统一', '精神統一', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从卡组中选择1张「精神统一」加入手卡。这张卡1回合只能使用1张。'),
(69802283, 'Gathering Light', '聚集之光', '集いし光', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：把自己场上1只怪兽和自己墓地1只「动力工具」同调怪兽或者7·8星的龙族同调怪兽除外，以对方场上1张卡为对象才能发动。那张卡破坏。 ②：自己场上的7星以上的同调怪兽的攻击力上升自己的除外状态的7星以上的同调怪兽数量×400。 ③：1回合1次，自己的除外状态的同调怪兽存在的场合，对方怪兽的攻击宣言时才能发动。那次攻击无效。'),
(87751584, 'Gatling Dragon', '机炮龙', 'ガトリング・ドラゴン', 'Fusion Monster', 'Machine', 'DARK', 8, 2600, 1200, '「左轮手枪龙」＋「回膛手枪龙」 投掷3个硬币。其中出现的与表侧硬币的数量同等数量的场上怪兽被破坏。这个效果1个回合1次，在自己的主要阶段使用。'),
(15561463, 'Gauntlet Launcher', '手甲射手', 'ガントレット・シューター', 'XYZ Monster', 'Warrior', 'EARTH', 6, 2400, 2800, '6星怪兽×2 自己的主要阶段时，把这张卡1个超量素材取除，选择对方场上1只怪兽才能发动。选择的怪兽破坏。'),
(79337169, 'Gauntlet Warrior', '手甲战士', 'ガントレット・ウォリアー', 'Effect Monster', 'Warrior', 'EARTH', 3, 400, 1600, '把这张卡解放发动。自己场上表侧表示存在的全部战士族怪兽的攻击力·守备力上升500，直到那些怪兽进行战斗的伤害步骤结束时适用。这个效果在对方回合也能发动。'),
(5818798, 'Gazelle the King of Mythical Beasts', '幻兽王 加赛尔', '幻獣王ガゼル', 'Normal Monster', 'Beast', 'EARTH', 4, 1500, 1200, '奔跑起来的速度太快，身姿看似幻影的野兽。'),
(23076639, 'Gazelle the King of Mythical Claws', '幻爪之王 加赛尔', '幻爪の王ガゼル', 'Effect Monster', 'Beast', 'EARTH', 4, 1500, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只恶魔族·5星怪兽或1张「合成兽融合」加入手卡。 ②：这张卡成为融合召唤的素材送去墓地的场合才能发动。从卡组把1只幻想魔族怪兽加入手卡。'),
(23536866, 'Gazer Shark', '间歇泉鲨', 'ゲイザー・シャーク', 'Effect Monster', 'Fish', 'WATER', 5, 1000, 1900, '把墓地的这张卡从游戏中除外，选择「间歇泉鲨」以外的自己墓地2只水属性·5星怪兽才能发动。选择的2只怪兽的效果无效特殊召唤，只用那2只为素材把1只水属性的超量怪兽超量召唤。「间歇泉鲨」的效果1回合只能使用1次。'),
(28912357, 'Gear Gigant X', '齿轮齿巨人 X', 'ギアギガント X', 'XYZ Monster', 'Machine', 'EARTH', 4, 2300, 1500, '机械族4星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。从自己的卡组·墓地选1只4星以下的机械族怪兽加入手卡。 ②：表侧表示的这张卡从场上离开时，以自己墓地1只3星以下的「齿轮齿轮」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(30190809, 'Gear Golem the Moving Fortress', '机动城的齿轮巨人', '機動砦のギア・ゴーレム', 'Effect Monster', 'Machine', 'EARTH', 4, 800, 2200, '这个效果在主要阶段一才能发动。支付800基本分。本回合这张卡可以对对方进行直接攻击。'),
(27979109, 'Gearbreed', '武装锻炼', '武装鍛錬', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己抽卡阶段作为进行通常抽卡的代替才能发动。从自己的卡组·墓地选1张装备魔法卡加入手卡。 ②：自己场上有装备魔法卡存在的场合，从自己墓地让1只战士族·炎属性怪兽或者二重怪兽回到卡组最下面才能发动。自己从卡组抽1张。'),
(423705, 'Gearfried the Iron Knight', '铁骑士 基亚·弗里德', '鉄の騎士 ギア・フリード', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 1600, '①：这张卡有装备卡被装备的场合发动。那些装备卡破坏。'),
(85651167, 'Gearfried the Red-Eyes Iron Knight', '真红眼铁骑士－机亚弗里德', '真紅眼の鉄騎士－ギア・フリード', 'Effect Monster', 'Warrior', 'DARK', 4, 1800, 1600, '①：1回合1次，这张卡有装备卡被装备的场合才能发动。那些装备卡破坏。那之后，可以选对方场上1张魔法·陷阱卡破坏。 ②：1回合1次，把这张卡装备的自己场上1张装备卡送去墓地，以自己墓地1只7星以下的「真红眼」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(57046845, 'Gearfried the Swordmaster', '剑圣-赤膊的基亚·弗里德', '剣聖－ネイキッド・ギア・フリード', 'Effect Monster', 'Warrior', 'LIGHT', 7, 2600, 2200, '这张卡不能通常召唤。「拘束解除」的效果才能特殊召唤。 ①：这张卡有装备卡被装备的场合，以对方场上1只怪兽为对象发动。那只对方怪兽破坏。'),
(29087919, 'Geargia Change', '齿轮齿轮变形', 'ギアギアチェンジ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「齿轮齿轮变形」在1回合只能发动1张。 ①：以自己墓地的「齿轮齿轮人」怪兽2只以上为对象才能发动（同名卡最多1张）。那些怪兽特殊召唤，只用那些怪兽为素材把1只超量怪兽超量召唤。'),
(47030842, 'Geargiaccelerator', '齿轮齿轮飙速车', 'ギアギアクセル', 'Effect Monster', 'Machine', 'EARTH', 4, 1400, 800, '自己场上有名字带有「齿轮齿轮」的怪兽存在的场合，这张卡可以从手卡表侧守备表示特殊召唤。此外，这张卡从场上送去墓地时，可以从自己墓地选择「齿轮齿轮加速人」以外的1只名字带有「齿轮齿轮」的怪兽加入手卡。'),
(6148016, 'Geargiagear', '齿轮齿轮齿轮', 'ギアギアギア', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从卡组把2只名字带有「齿轮齿轮人」的怪兽特殊召唤。这个效果特殊召唤的怪兽的等级上升1星。「齿轮齿轮齿轮」在1回合只能发动1张。'),
(19891310, 'Geargiagear Gigant XG', '齿轮齿轮齿轮 X巨人', 'ギアギアギア XG', 'XYZ Monster', 'Machine', 'EARTH', 3, 2500, 1300, '3星怪兽×3 自己场上的机械族怪兽进行战斗的战斗步骤时，把这张卡1个超量素材取除才能发动。对方场上表侧表示存在的卡的效果直到那次伤害步骤结束时无效，直到那次伤害步骤结束时对方不能把魔法·陷阱·效果怪兽的效果发动。此外，这张卡从场上离开时，可以从自己墓地选择这张卡以外的1张名字带有「齿轮齿轮」的卡加入手卡。'),
(92693205, 'Geargianchor', '齿轮齿轮抛锚人', 'ギアギアンカー', 'Effect Monster', 'Machine', 'EARTH', 4, 1800, 500, '①：自己主要阶段才能发动。这张卡变成里侧守备表示（1回合只有1次）。 ②：这张卡反转的场合才能发动。选最多有这张卡以外的自己场上的「齿轮齿轮」怪兽数量的场上的怪兽破坏。'),
(71786742, 'Geargiano', '齿轮齿轮人', 'ギアギアーノ', 'Effect Monster', 'Machine', 'EARTH', 3, 500, 1000, '把这张卡解放，选择自己墓地存在的1只4星的机械族怪兽发动。选择的怪兽从墓地特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(1045143, 'Geargiano Mk-II', '齿轮齿轮人 Mk－Ⅱ', 'ギアギアーノ Mk－Ⅱ', 'Effect Monster', 'Machine', 'EARTH', 3, 1000, 500, '这张卡召唤·反转召唤成功时，可以从自己的手卡·墓地选1只名字带有「齿轮齿轮」的怪兽表侧守备表示特殊召唤。'),
(45286019, 'Geargiano Mk-III', '齿轮齿轮人 Mk－Ⅲ', 'ギアギアーノ Mk－Ⅲ', 'Effect Monster', 'Machine', 'EARTH', 3, 1000, 1000, '这张卡用名字带有「齿轮齿轮」的卡的效果特殊召唤成功时，可以从自己的手卡·墓地选「齿轮齿轮人 Mk-3」以外的1只名字带有「齿轮齿轮」的怪兽表侧守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。「齿轮齿轮人 Mk-3」的效果1回合只能使用1次，这个效果发动的回合，自己不能把名字带有「齿轮齿轮」的怪兽以外的怪兽特殊召唤。'),
(923596, 'Geargiarmor', '齿轮齿轮铠甲人', 'ギアギアーマー', 'Effect Monster', 'Machine', 'EARTH', 4, 1100, 1900, '这张卡1回合只有1次可以变成里侧守备表示。这张卡反转时，可以从卡组把「齿轮齿轮铠甲人」以外的1只名字带有「齿轮齿轮」的怪兽加入手卡。'),
(73428497, 'Geargiarsenal', '齿轮齿轮武库人', 'ギアギアーセナル', 'Effect Monster', 'Machine', 'EARTH', 4, 1500, 500, '这张卡的攻击力上升自己场上的名字带有「齿轮齿轮」的怪兽数量×200的数值。此外，可以把这张卡解放，从卡组把「齿轮齿轮武库人」以外的1只名字带有「齿轮齿轮」的怪兽表侧守备表示特殊召唤。'),
(72370114, 'Geargiattacker', '齿轮齿轮攻击人', 'ギアギアタッカー', 'Effect Monster', 'Machine', 'EARTH', 4, 1900, 100, '这张卡1回合只有1次可以变成里侧守备表示。这张卡反转时，可以选最多有这张卡以外的自己场上的名字带有「齿轮齿轮」的怪兽数量的场上的魔法·陷阱卡破坏。'),
(47687766, 'Geargiauger', '齿轮齿轮潜掘机', 'ギアギアングラー', 'Effect Monster', 'Machine', 'EARTH', 4, 500, 500, '①：这张卡召唤成功时才能发动。从卡组把「齿轮齿轮钻地人」以外的1只机械族·地属性·4星怪兽加入手卡。这个回合，自己不能攻击宣言，不是机械族怪兽不能特殊召唤。'),
(45458027, 'Gearspring Spirit', '上弦式神', 'ネジマキシキガミ', 'Effect Monster', 'Machine', 'DARK', 8, 100, 100, '这张卡不能通常召唤。自己墓地的怪兽只有机械族怪兽的场合可以特殊召唤。 ①：1回合1次，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成0。'),
(37694547, 'Geartown', '齿轮镇', '歯車街', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，双方玩家可以把「古代的机械」怪兽召唤的场合需要的解放减少1只。 ②：这张卡被破坏送去墓地时才能发动。从自己的手卡·卡组·墓地把1只「古代的机械」怪兽特殊召唤。'),
(40392714, 'Geira Guile the Cubic King', '方界帝 疾风之盖伊罗', '方界帝ゲイラ・ガイル', 'Effect Monster', 'Fairy', 'WIND', 2, NULL, NULL, '这张卡不能通常召唤。把自己场上1只「方界」怪兽送去墓地的场合可以特殊召唤。 ①：这个方法特殊召唤的这张卡的攻击力上升800。 ②：这张卡从手卡的特殊召唤成功的场合发动。给与对方800伤害。 ③：这张卡战斗的伤害步骤结束时，以自己墓地最多2只「方界胤 毗贾姆」为对象才能发动。这张卡送去墓地，作为对象的怪兽特殊召唤。那之后，可以从卡组把1只「方界帝 神火之德拉耆尼」加入手卡。'),
(26913989, 'Geistgrinder Golem', '幽魂拷问魔像', 'ガイストーチ・ゴーレム', 'Effect Monster', 'Fiend', 'DARK', 8, 3000, 300, '自己对「亡灵拷问巨人」1回合只能有1次特殊召唤。 ①：把手卡1只「于贝尔」怪兽给对方观看才能发动。这张卡从手卡往对方场上特殊召唤。那之后，可以把给人观看的怪兽在自己场上特殊召唤。 ②：1回合1次，这张卡和「于贝尔」怪兽进行战斗的伤害计算时发动。对方回复3000基本分。 ③：这张卡在墓地存在的状态，自己把「于贝尔」特殊召唤的场合才能发动。这张卡在对方场上特殊召唤。'),
(11662742, 'Gellenduo', '双生天使', 'ジェルエンデュオ', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1700, NULL, '①：天使族·光属性怪兽上级召唤的场合，这张卡可以作为2只的数量解放。 ②：这张卡不会被战斗破坏。 ③：自己因战斗·效果受到伤害的场合发动。场上的表侧表示的这张卡破坏。'),
(57753602, 'Gem Flash Energy', '宝石闪耀能量', 'ジェムフラッシュエナジー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '每次自己的准备阶段给与对方基本分场上表侧表示存在的永续魔法卡数量×300的数值的伤害。'),
(27004302, 'Gem-Armadillo', '宝石犰狳', 'ジェムレシス', 'Effect Monster', 'Rock', 'EARTH', 4, 1700, 500, '①：这张卡召唤时才能发动。从卡组把1只「宝石骑士」怪兽加入手卡。'),
(19019586, 'Gem-Elephant', '宝石象', 'ジェムエレファント', 'Effect Monster', 'Rock', 'EARTH', 3, 400, 1900, '自己的主要阶段时，可以让场上表侧表示存在的这张卡回到手卡。此外，这张卡进行战斗的伤害计算时只有1次，从手卡把1只通常怪兽送去墓地才能发动。这张卡的守备力只在那次伤害计算时上升1000。'),
(41777, 'Gem-Enhancement', '宝石优化', 'ジェム・エンハンス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上存在的1只名字带有「宝石骑士」的怪兽解放，选择自己墓地存在的1只名字带有「宝石骑士」的怪兽发动。选择的怪兽从墓地特殊召唤。'),
(90019393, 'Gem-Knight Alexandrite', '宝石骑士・紫翠玉', 'ジェムナイト・アレキサンド', 'Effect Monster', 'Rock', 'EARTH', 4, 1800, 1200, '①：把这张卡解放才能发动。从卡组把1只「宝石骑士」通常怪兽特殊召唤。'),
(72056560, 'Gem-Knight Amber', '宝石骑士·琥珀', 'ジェムナイト・アンバー', 'Gemini Monster', 'Thunder', 'EARTH', 4, 1600, 1400, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当成通常召唤使用的再度召唤，这张卡变成当作效果怪兽使用并得到以下效果。 ●1回合1次，可以从手卡把1张名字带有「宝石骑士」的卡送去墓地，选择从游戏中除外的1只自己怪兽回到手卡。'),
(71616908, 'Gem-Knight Amethyst', '宝石骑士・紫水晶', 'ジェムナイト・アメジス', 'Fusion Monster', 'Aqua', 'EARTH', 7, 1950, 2450, '「宝石骑士」怪兽＋水族怪兽 这张卡用融合召唤才能从额外卡组特殊召唤。 ①：这张卡从场上送去墓地的场合发动。场上的里侧表示的魔法·陷阱卡全部回到手卡。'),
(13108445, 'Gem-Knight Aquamarine', '宝石骑士・海蓝玉', 'ジェムナイト・アクアマリナ', 'Fusion Monster', 'Aqua', 'EARTH', 6, 1400, 2600, '「宝石骑士·青玉」＋「宝石骑士」怪兽 这张卡用以上记的卡为融合素材的融合召唤才能从额外卡组特殊召唤。 ①：这张卡攻击的场合，战斗阶段结束时变成守备表示。 ②：这张卡从场上送去墓地的场合，以对方场上1张卡为对象发动。那张对方的卡回到手卡。'),
(67985943, 'Gem-Knight Citrine', '宝石骑士・橙黄晶', 'ジェムナイト・マディラ', 'Fusion Monster', 'Pyro', 'EARTH', 7, 2200, 1950, '「宝石骑士」怪兽＋炎族怪兽 这张卡用融合召唤才能从额外卡组特殊召唤。 ①：这张卡进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。'),
(76908448, 'Gem-Knight Crystal', '宝石骑士・水晶', 'ジェムナイト・クリスタ', 'Normal Monster', 'Rock', 'EARTH', 7, 2450, 1950, '把水晶力量优化，变为战斗力来战斗的宝石骑士之上级战士。他可是会运用那高攻击力来压倒敌人哟。不过，自己也时常感到那优化的力量有限，他很珍视与同伴们之间的团结合作。'),
(24220368, 'Gem-Knight Dispersion', '宝石骑士彩光', 'ジェムナイト・ディスパージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●自己的手卡·场上的怪兽作为融合素材，把1只「宝石骑士」融合怪兽融合召唤。自己墓地有「宝石骑士融合」存在的场合，卡组·额外卡组的岩石族以外的「宝石骑士」怪兽也能有最多2只作为融合素材。 ●自己的卡组·除外状态的1只「宝石」怪兽加入手卡。这个回合的主要阶段内，对方受到的效果伤害变成一半。'),
(69243722, 'Gem-Knight Emerald', '宝石骑士·翠玉', 'ジェムナイト・エメラル', 'Effect Monster', 'Rock', 'EARTH', 4, 1800, 800, '①：把自己场上1只表侧表示的通常怪兽和这张卡除外，以自己墓地1只「宝石骑士」融合怪兽为对象才能发动。那只怪兽特殊召唤。'),
(1264319, 'Gem-Knight Fusion', '宝石骑士结合', 'ジェムナイト・フュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的手卡·场上的怪兽作为融合素材，把1只「宝石骑士」融合怪兽融合召唤。 ②：这张卡在墓地存在的场合，从自己墓地把1只「宝石骑士」怪兽除外才能发动。这张卡加入手卡。'),
(91731841, 'Gem-Knight Garnet', '宝石骑士・石榴石', 'ジェムナイト・ガネット', 'Normal Monster', 'Pyro', 'EARTH', 4, 1900, NULL, '拥有石榴石力量的宝石骑士之战士。火焰铁拳会粉碎所有敌人。'),
(88225269, 'Gem-Knight Hollowcore', '宝石骑士・虚炼原核', 'ジェムナイト・ヴォイドルーツ', 'Effect Monster', 'Fiend', 'DARK', 7, 1950, 2450, '这个卡名的①②的效果1回合各能使用1次。 ①：把1只「宝石骑士」通常怪兽或1张「宝石骑士融合」从卡组送去墓地才能发动。这张卡从手卡守备表示特殊召唤。 ②：自己场上有「宝石骑士」融合怪兽存在，对方把效果发动时，从自己墓地把包含这张卡的3张「宝石骑士」卡除外才能发动。那个效果无效。那之后，自己场上的全部「宝石骑士」怪兽的攻击力上升1000。'),
(45662855, 'Gem-Knight Iolite', '宝石骑士·堇青', 'ジェムナイト・アイオーラ', 'Gemini Monster', 'Aqua', 'EARTH', 4, 1300, 2000, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当成通常召唤使用的再度召唤，这张卡变成当作效果怪兽使用并得到以下效果。 ●1回合1次，可以把自己墓地存在的1只名字带有「宝石」的怪兽从游戏中除外，选择自己墓地存在的1张名字带有「宝石骑士」的卡加入手卡。'),
(19355597, 'Gem-Knight Lady Brilliant Diamond', '宝石骑士女郎・璀璨辉钻', 'ジェムナイトレディ・ブリリアント・ダイヤ', 'Fusion Monster', 'Rock', 'EARTH', 10, 3400, 2000, '「宝石骑士」怪兽×3 这张卡用以上记的卡为融合素材的融合召唤才能从额外卡组特殊召唤。自己对「宝石骑士女郎·亮钻」1回合只能有1次特殊召唤。 ①：1回合1次，自己主要阶段才能发动。自己场上1只表侧表示的「宝石骑士」怪兽送去墓地，从额外卡组把1只「宝石骑士」融合怪兽无视召唤条件特殊召唤。'),
(47611119, 'Gem-Knight Lady Lapis Lazuli', '宝石骑士女郎・金碧琉璃', 'ジェムナイトレディ・ラピスラズリ', 'Fusion Monster', 'Rock', 'EARTH', 5, 2400, 1000, '「宝石骑士·小琉」＋「宝石骑士」怪兽 这张卡用以上记的卡为融合素材的融合召唤才能从额外卡组特殊召唤。自己对「宝石骑士女郎·琉璃」1回合只能有1次特殊召唤。 ①：1回合1次，自己主要阶段才能发动。从卡组·额外卡组把1只「宝石骑士」怪兽送去墓地，给与对方为场上的特殊召唤的怪兽数量×500伤害。'),
(55610199, 'Gem-Knight Lady Rose Diamond', '宝石骑士女郎・蔷薇辉钻', 'ジェムナイトレディ・ローズ・ダイヤ', 'Fusion Monster', 'Fairy', 'EARTH', 8, 2700, 2400, '「宝石骑士」怪兽＋天使族怪兽 ①：只要这张卡在怪兽区域存在，对方回合只有1次，自己场上的「宝石骑士」怪兽不会被效果破坏。 ②：自己回合，对方把怪兽的效果发动时，从自己墓地把1张「宝石骑士」卡除外，以对方场上1张表侧表示卡为对象才能发动。那张卡破坏。'),
(99645428, 'Gem-Knight Lapis', '宝石骑士・金碧', 'ジェムナイト・ラピス', 'Normal Monster', 'Rock', 'EARTH', 3, 1200, 100, '常担心同伴健康的治愈战士。与小璃非常要好。'),
(81846636, 'Gem-Knight Lazuli', '宝石骑士・琉璃', 'ジェムナイト・ラズリー', 'Effect Monster', 'Rock', 'EARTH', 1, 600, 100, '①：这张卡被效果送去墓地的场合，以自己墓地1只通常怪兽为对象才能发动。那只怪兽加入手卡。'),
(39512984, 'Gem-Knight Master Diamond', '宝石骑士统领・辉钻', 'ジェムナイトマスター・ダイヤ', 'Fusion Monster', 'Rock', 'EARTH', 9, 2900, 2500, '「宝石骑士」怪兽×3 这张卡用融合召唤才能从额外卡组特殊召唤。 ①：这张卡的攻击力上升自己墓地的「宝石」怪兽数量×100。 ②：1回合1次，从自己墓地把1只7星以下的「宝石骑士」融合怪兽除外才能发动。这张卡直到结束阶段得到和除外的怪兽的原本的卡名·效果相同的卡名·效果。'),
(25342956, 'Gem-Knight Master Diamond Dispersion', '宝石骑士统领・辉钻－彩光', 'ジェムナイトマスター・ダイヤ－ディスパージョン', 'Fusion Monster', 'Rock', 'EARTH', 9, 3000, 2600, '「宝石」怪兽×3 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，把场上的这张卡送去墓地才能发动。从自己的额外卡组·墓地把最多3只岩石族以外的「宝石」怪兽无视召唤条件特殊召唤（同名卡最多1张）。这个回合，自己不是融合怪兽不能从额外卡组特殊召唤。 ②：这张卡在墓地存在的状态，自己的「宝石骑士」融合怪兽被战斗破坏时才能发动。这张卡特殊召唤。');